// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(address account) internal {
        try c.XBornID() {} catch { return; }
        assertTrue(c.balanceOf(account) <= 500000000e18);
    }

    function testFuzz_run(address account) public {
        vm.assume(account.code.length == 0 && uint160(account) > 0xffff && account != address(this) && account != address(c) && account != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && account != 0x000000000000000000636F6e736F6c652e6c6f67 && account != 0x4e59b44847b379578588920cA78FbF26c0B4956C && account != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(account);
    }

    receive() external payable {}
}
